style.css:
@-moz-document domain("meet.google.com") {
/* MAIN BACKGROUND */
body,
html {
    background-color: #fff0f5 !important;
}

/* MAIN PANELS */
div[role="main"],
div[role="dialog"],
section {
    border-radius: 18px !important;
}

/* BUTTONS */
button {
    background-color: #f8c8dc !important;
    color: #75445b !important;
    border-radius: 20px !important;
    border: 1px solid #f2aeca !important;
    transition: all 0.25s ease !important;
}

button:hover {
    background-color: #f4aeca !important;
    color: #ffffff !important;
    transform: scale(1.03);
}

/* MEETING CONTROL BAR */
div[role="toolbar"] {
    background: linear-gradient(
        90deg,
        #fce4ec,
        #f8c8dc,
        #f3d5f5
    ) !important;
    border-radius: 25px !important;
    padding: 8px !important;
}

/* ICONS */
button svg {
    color: #a65d7c !important;
    fill: currentColor;
}

/* TEXT */
body,
span,
p {
    font-family: "Arial", sans-serif !important;
}

/* CHAT AND SIDE PANELS */
div[role="complementary"],
div[role="tabpanel"] {
    background-color: #fff5f8 !important;
    border-radius: 18px !important;
}

/* INPUT BOXES */
input,
textarea {
    background-color: #fff0f5 !important;
    border: 1px solid #efb5cc !important;
    border-radius: 12px !important;
    color: #75445b !important;
}

/* LINKS */
a {
    color: #d875a0 !important;
}

/* SCROLLBAR */
::-webkit-scrollbar {
    width: 8px;
}

::-webkit-scrollbar-thumb {
    background-color: #edb3cc;
    border-radius: 10px;
}

::-webkit-scrollbar-track {
    background-color: #fff0f5;
}

/* SELECTION */
::selection {
    background: #f4b6d0;
    color: #75445b;
}
}
